### 2. Kafka 설정 수정

다음으로, `docker-compose.yml` 파일에서 Kafka 설정을 수정하여 작성한 직렬화 및 역직렬화 클래스를 사용하도록 합니다.

#### `docker-compose.yml`

```yaml
version: '3.8'

services:
 mysql:
 image: mysql:8.0
 container_name: shop_mysql
 ports:
 - "3306:3306"
 environment:
 MYSQL_ROOT_PASSWORD: root
 MYSQL_DATABASE: shop_db
 MYSQL_USER: shop_user
 MYSQL_PASSWORD: shop_password
 command:
 - --character-set-server=utf8mb4
 - --collation-server=utf8mb4_unicode_ci
 volumes:
 - mysql_data:/var/lib/mysql

 zookeeper:
 image: confluentinc/cp-zookeeper:7.5.0
 container_name: shop_zookeeper
 ports:
 - "2181:2181"
 environment:
 ZOOKEEPER_CLIENT_PORT: 2181 # Zookeeper 클라이언트가 연결할 포트
 ZOOKEEPER_TICK_TIME: 2000 # Zookeeper의 틱 시간 (밀리초 단위)

 kafka:
 image: confluentinc/cp-kafka:7.5.0
 container_name: shop_kafka
 ports:
 - "9092:9092"
 environment:
 KAFKA_BROKER_ID: 1 # Kafka 브로커의 고유 식별자
 KAFKA_ZOOKEEPER_CONNECT: shop_zookeeper:2181 # Kafka가 연결할 Zookeeper 주소와 포트
 KAFKA_ADVERTISED_LISTENERS: PLAINTEXT://localhost:9092 # 클라이언트가 Kafka 브로커에 연결할 때 사용할 주소와 포트
 ALLOW_PLAINTEXT_LISTENER: 'yes' # 평문 리스너 허용
 depends_on:
 - zookeeper # Zookeeper가 먼저 시작되도록 의존성 설정
 volumes:
 - kafka_data:/var/lib/kafka/data # Kafka 데이터를 영속화하기 위한 볼륨

 kafka-ui:
 image: provectuslabs/kafka-ui:latest
 container_name: shop_kafka_ui
 ports:
 - "8080:8080"
 environment:
 KAFKA_CLUSTERS_0_NAME: local # Kafka 클러스터의 이름
 KAFKA_CLUSTERS_0_BOOTSTRAPSERVERS: shop_kafka:9092 # Kafka 클러스터의 부트스트랩 서버 주소
 depends_on:
 - kafka # Kafka가 먼저 시작되도록 의존성 설정

volumes:
 mysql_data: # MySQL 데이터를 영속화하기 위한 볼륨
 kafka_data: # Kafka 데이터를 영속화하기 위한 볼륨
 zookeeper_data: # Zookeeper 데이터를 영속화하기 위한 볼륨
```

### 3. Kafka Producer 및 Consumer 설정 수정

Kafka Producer와 Consumer에서 작성한 직렬화 및 역직렬화 클래스를 사용하도록 설정해야 합니다.

#### Kafka Producer 설정 예제

```java
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.apache.kafka.common.serialization.StringSerializer;

import java.util.Properties;

public class OrderCreatedEventProducer {
 public static void main(String[] args) {
 Properties props = new Properties();
 props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
 props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
 props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, OrderCreatedEventSerializer.class.getName());

 KafkaProducer<String, OrderCreatedEvent> producer = new KafkaProducer<>(props);

 OrderCreatedEvent event = new OrderCreatedEvent();
 // event에 필요한 데이터 설정

 ProducerRecord<String, OrderCreatedEvent> record = new ProducerRecord<>("order-created-topic", event);
 producer.send(record);

 producer.close();
 }
}
```

#### Kafka Consumer 설정 예제

```java
import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.clients.consumer.ConsumerRecords;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.common.serialization.StringDeserializer;

import java.time.Duration;
import java.util.Collections;
import java.util.Properties;

public class OrderCreatedEventConsumer {
 public static void main(String[] args) {
 Properties props = new Properties();
 props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
 props.put(ConsumerConfig.GROUP_ID_CONFIG, "order-created-group");
 props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
 props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, OrderCreatedEventDeserializer.class.getName());

 KafkaConsumer<String, OrderCreatedEvent> consumer = new KafkaConsumer<>(props);
 consumer.subscribe(Collections.singletonList("order-created-topic"));

 while (true) {
 ConsumerRecords<String, OrderCreatedEvent> records = consumer.poll(Duration.ofMillis(100));
 for (ConsumerRecord<String, OrderCreatedEvent> record : records) {
 OrderCreatedEvent event = record.value();
 // event 처리 로직
 System.out.println("Received event: " + event);
 }
 }
 }
}
```

### 4. 의존성 추가

`ObjectMapper`를 사용하기 위해 `Jackson` 라이브러리를 프로젝트에 추가해야 합니다. 예를 들어, Maven을 사용하는 경우 `pom.xml`에 다음과 같이 의존성을 추가합니다:

```xml
<dependency>
 <groupId>com.fasterxml.jackson.core</groupId>
 <artifactId>jackson-databind</artifactId>
 <version>2.15.2</version> <!-- 최신 버전으로 변경 가능 -->
</dependency>
```

Gradle을 사용하는 경우 `build.gradle`에 다음과 같이 의존성을 추가합니다:

```groovy
dependencies {
 implementation 'com.fasterxml.jackson.core:jackson-databind:2.15.2' // 최신 버전으로 변경 가능
}
```

